import sys
from collections import defaultdict

def min_cost_to_paint_white(n, m, rectangles):
    # Initialize the cost matrix
    cost = [[0] * (n + 1) for _ in range(n + 1)]

    # Mark the black cells
    for x1, y1, x2, y2 in rectangles:
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                cost[i][j] = 1

    # Calculate the minimum cost to paint the grid white
    total_cost = 0
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if cost[i][j] == 1:
                # Find the smallest rectangle that covers this black cell
                min_height = float('inf')
                min_width = float('inf')
                for k in range(i, n + 1):
                    if all(cost[k][l] == 0 for l in range(j, n + 1)):
                        break
                    for l in range(j, n + 1):
                        if cost[k][l] == 1:
                            min_height = min(min_height, k - i + 1)
                            min_width = min(min_width, l - j + 1)
                        else:
                            break
                    if min_height != float('inf'):
                        break
                total_cost += min(min_height, min_width)
                # Mark the entire rectangle as painted
                for k in range(i, i + min_height):
                    for l in range(j, j + min_width):
                        cost[k][l] = 0

    return total_cost

